<?php $workload=App\Services\Query::teamWorkload($section==='all'?0:(int)$project['id'],$filters); ?>
<section class="panel team-workload"><div class="panel-header"><div><h2>Le travail par équipe</h2><p>Tickets correspondant aux filtres, tous responsables individuels confondus.</p></div><?= icon('chart') ?></div>
<div class="table-scroll"><table><thead><tr><th>Équipe</th><th>Tickets</th><th>Terminés</th><th>Avancement moyen</th><th>Heures estimées</th></tr></thead><tbody><?php foreach($workload as $row): ?><tr><td><a href="<?= e(query_url('/list',$baseQuery,['team'=>$row['team_id']??'none'])) ?>"><?= e($row['name']) ?></a></td><td><?= (int)$row['total'] ?></td><td><?= (int)$row['done'] ?></td><td><?= (int)round((float)$row['progress']) ?> %</td><td><?= $row['hours']===null?'—':e(number_format((float)$row['hours'],2,',',' ')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$workload): ?><p class="muted">Aucun ticket pour ces critères.</p><?php endif; ?><p class="help-text">Avancement manuel moyen des tickets ; heures renseignées uniquement. Les tickets sans estimation ne valent pas zéro.</p></section>
